import{_ as e,o as a,c as s,a2 as r}from"./chunks/framework.DA69LXMH.js";const p=JSON.parse('{"title":"Solução de Problemas & FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"suporte/solucao-problemas.md","filePath":"suporte/solucao-problemas.md"}'),t={name:"suporte/solucao-problemas.md"};function i(n,o,d,c,l,u){return a(),s("div",null,[...o[0]||(o[0]=[r('<h1 id="solucao-de-problemas-faq" tabindex="-1">Solução de Problemas &amp; FAQ <a class="header-anchor" href="#solucao-de-problemas-faq" aria-label="Permalink to &quot;Solução de Problemas &amp; FAQ&quot;">​</a></h1><p>Consulte as respostas e procedimentos recomendados para solucionar dúvidas técnicas e comportamentos inesperados no uso do <strong>EchoBot</strong>.</p><hr><h3 id="❓-o-echobot-nao-esta-reconhecendo-meu-microfone-ou-audio" tabindex="-1">❓ O EchoBot não está reconhecendo meu microfone ou áudio <a class="header-anchor" href="#❓-o-echobot-nao-esta-reconhecendo-meu-microfone-ou-audio" aria-label="Permalink to &quot;❓ O EchoBot não está reconhecendo meu microfone ou áudio&quot;">​</a></h3><ol><li><strong>Permissões do Windows:</strong> Vá em <strong>Configurações do Windows &gt; Privacidade e Segurança &gt; Microfone</strong>. Certifique-se de que a opção <em>&quot;Permitir que aplicativos da área de trabalho acessem seu microfone&quot;</em> está <strong>Ativada</strong>.</li><li><strong>Seleção de Dispositivo:</strong> No Gravador WebRTC da sessão, verifique se você selecionou o dispositivo correto de entrada (headset ou microfone principal).</li><li><strong>Áudio do Sistema (Loopback):</strong> Se estiver gravando o som dos jogadores via navegador, certifique-se de autorizar o compartilhamento de áudio da aba ou do sistema na janela de permissão do navegador.</li></ol><hr><h3 id="❓-como-garantir-que-a-aceleracao-por-gpu-cuda-esta-ativa" tabindex="-1">❓ Como garantir que a aceleração por GPU (CUDA) está ativa? <a class="header-anchor" href="#❓-como-garantir-que-a-aceleracao-por-gpu-cuda-esta-ativa" aria-label="Permalink to &quot;❓ Como garantir que a aceleração por GPU (CUDA) está ativa?&quot;">​</a></h3><ol><li><strong>Driver NVIDIA:</strong> Certifique-se de ter os drivers mais recentes da sua GPU instalados via GeForce Experience ou site oficial da NVIDIA.</li><li><strong>Configuração no EchoBot:</strong> Em <strong>Configurações ➔ Motor STT</strong>, defina o dispositivo de execução como <strong><code>cuda</code></strong> (ou <code>auto</code>).</li><li><strong>Logs do Whisper Sidecar:</strong> Abra o Console de Logs (<code>/logs</code> ou ícone da bandeja). Você deverá ver a mensagem indicando carregamento das DLLs do CUDA Toolkit (<code>cublas64_12.dll</code> / <code>cudnn_ops64_9.dll</code>).</li><li><strong>Fallback:</strong> Se o sistema não detectar os binários do CUDA, ele alternará automaticamente e com segurança para o modo CPU (<code>whisper.cpp</code>).</li></ol><hr><h3 id="❓-onde-ficam-salvas-as-minhas-campanhas-e-gravacoes" tabindex="-1">❓ Onde ficam salvas as minhas campanhas e gravações? <a class="header-anchor" href="#❓-onde-ficam-salvas-as-minhas-campanhas-e-gravacoes" aria-label="Permalink to &quot;❓ Onde ficam salvas as minhas campanhas e gravações?&quot;">​</a></h3><p>Por padrão, no Windows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%LOCALAPPDATA%\\EchoBotData</span></span></code></pre></div><p>Dentro deste diretório estão:</p><ul><li><code>data/</code>: Banco de dados Flat-File com mundos, campanhas, sessões e compêndio.</li><li><code>recordings/</code>: Gravações de áudio salvas em formato Ogg/Opus.</li><li><code>models/</code>: Modelos baixados de IA acústica e vozes (Whisper e Kokoro).</li></ul><p>Para transferir todos os dados para outro HD ou SSD com mais espaço livre, utilize o assistente em <strong>Configurações ➔ Armazenamento ➔ Migrar Dados</strong>.</p><hr><h3 id="❓-os-jogadores-nao-conseguem-acessar-o-portal-do-jogador" tabindex="-1">❓ Os jogadores não conseguem acessar o Portal do Jogador <a class="header-anchor" href="#❓-os-jogadores-nao-conseguem-acessar-o-portal-do-jogador" aria-label="Permalink to &quot;❓ Os jogadores não conseguem acessar o Portal do Jogador&quot;">​</a></h3><ol><li><strong>Túnel Ativo:</strong> No modal de colaboração, certifique-se de que o botão <strong>Iniciar Túnel Cloudflare</strong> foi clicado e exibe o status <em>&quot;Ativo&quot;</em>.</li><li><strong>Rede Local (LAN):</strong> Caso prefira conectar sem túnel pela mesma rede Wi-Fi, certifique-se de que o Firewall do Windows não está bloqueando conexões de entrada na porta <code>8000</code>.</li><li><strong>Acesso aos Dados:</strong> Lembre-se de que visitantes externos são restritos pelo Firewall do Mestre e só conseguem acessar <code>/player</code> (todas as telas de configuração e sessões são protegidas).</li></ol><hr><h3 id="❓-como-coletar-logs-e-obter-suporte-tecnico" tabindex="-1">❓ Como coletar logs e obter suporte técnico? <a class="header-anchor" href="#❓-como-coletar-logs-e-obter-suporte-tecnico" aria-label="Permalink to &quot;❓ Como coletar logs e obter suporte técnico?&quot;">​</a></h3><ol><li>Acesse o <strong>Console de Logs Administrativo</strong> navegando para:<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:8000/logs</span></span></code></pre></div></li><li>Você poderá filtrar por nível de severidade (<em>ERROR</em>, <em>WARN</em>, <em>INFO</em>) ou por componente (<em>Whisper Sidecar, Voice Bridge, Backend API</em>).</li><li>Clique em <strong>Exportar Logs (.txt)</strong> para gerar um arquivo detalhado para enviar ao suporte no repositório oficial do GitHub.</li></ol>',21)])])}const g=e(t,[["render",i]]);export{p as __pageData,g as default};
